function systems() {
    return ["ALL", "POWER", "COMPUTE", "FLIGHT SENSORS", "HYDRAULICS", "FUEL", "DATA", "NAVIGATION", "RECORDER", "COMMUNICATIONS", "ENVIRONMENTAL", "ACTUATION", "ASSURANCE"]
}

function categories(system) {
    if (system === "ALL") return ["ALL"]
    var map = {
        "POWER": ["ALL", "Distribution", "Sources", "Quality"],
        "COMPUTE": ["ALL", "Thermal", "Runtime", "Timing"],
        "FLIGHT SENSORS": ["ALL", "Attitude", "Air Data", "Quality"],
        "HYDRAULICS": ["ALL", "Pressure", "Thermal", "Evidence"],
        "FUEL": ["ALL", "Quantity", "Trend", "Coherence"],
        "DATA": ["ALL", "Sequence", "Timing", "Schema"],
        "NAVIGATION": ["ALL", "Coherence", "Quality", "Context"],
        "RECORDER": ["ALL", "Integrity", "Replay", "Export"],
        "COMMUNICATIONS": ["ALL", "Link", "Timing", "Availability"],
        "ENVIRONMENTAL": ["ALL", "Temperature", "Pressure", "Cooling"],
        "ACTUATION": ["ALL", "Feedback", "Timing", "Symmetry"],
        "ASSURANCE": ["ALL", "Gates", "Evidence", "Consistency"]
    }
    return map[system] || ["ALL"]
}
